function buildManifest() {
  const tokensList = [];
  for (const [k, v] of Object.entries(tokens.color.light)) tokensList.push({ name: `--color-${k}`, value: v, kind: 'color', definedIn: 'colors_and_type.css' });
  for (const group of ['radius', 'shadow', 'text', 'space', 'layout', 'z']) for (const [k, v] of Object.entries(tokens[group])) tokensList.push({ name: `--${group}-${k}`, value: v, kind: group, definedIn: 'colors_and_type.css' });
  return {
    namespace: 'PemaDesignSystem',
    components: [],
    startingPoints: [],
    cards: CARDS.map(([file, group, viewport, subtitle, name]) => ({ path: `preview/${file}.html`, group, viewport, subtitle, name })),
    templates: [],
    hasThumbnailHtml: false,
    globalCssPaths: ['colors_and_type.css'],
    tokens: tokensList,
    themes: [{ name: 'dark', selector: '.dark, [data-theme="dark"]' }],
    fonts: [],
    brandFonts: [{ family: 'Be Vietnam Pro', status: 'google-fonts-link', tokens: ['--font-family-ui'], path: 'colors_and_type.css' }],
    source: 'repo: design-system/ (tokens.json is the single source; see README.md)',
  };
}

// ---------------------------------------------------------------------------------------------------------------------
// collect, then write or compare
// ---------------------------------------------------------------------------------------------------------------------
function buildAll() {
  const blocks = parseBlocks();
  const names = kmpNames();
  const files = new Map();
  files.set('colors_and_type.css', buildCss());
  files.set('colors.md', buildColors());
  files.set('typography.md', buildTypography());
  files.set('spacing-radius-elevation.md', buildSpacing());
  for (const b of blocks) files.set(`components/${b.name}.md`, buildComponent(b, names));
  files.set('components/INDEX.md', buildComponentIndex(blocks, names));
  for (const [file, , , , , render] of CARDS) files.set(`preview/${file}.html`, render());
  files.set('_ds_manifest.json', JSON.stringify(buildManifest(), null, 2) + '\n');
  return { files, blocks };
}

function main() {
  const { files, blocks } = buildAll();
  const problems = [];
  for (const [rel, text] of files) {
    const target = path.join(DS, rel);
    const have = fs.existsSync(target) ? read(target) : null;
    if (CHECK) {
      if (have !== text) problems.push(`${rel} ${have === null ? 'is missing' : 'is stale'}`);
      continue;
    }
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, text);
  }
  if (CHECK) {
    // a page of a block that no longer exists in BLOCKS.md
    const wanted = new Set(blocks.map((b) => `${b.name}.md`).concat('INDEX.md'));
    for (const f of fs.readdirSync(path.join(DS, 'components'))) if (!wanted.has(f)) problems.push(`components/${f} has no block in BLOCKS.md`);
    if (problems.length) {
      problems.forEach((p) => console.error('FAILED ' + p));
      console.error('run: node design-system/scripts/build.cjs');
      process.exit(1);
    }
    console.log(`generated files up to date: ${files.size} files, ${blocks.length} component pages`);
  } else {
    console.log(`wrote ${files.size} files (${blocks.length} component pages)`);
  }
}

if (require.main === module) main();

module.exports = { parseBlocks, kmpNames, kmpStatus, KMP_OUTSIDE, buildAll, contrast, tokens };
